import{_ as t,c as i,o as e,ag as s}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),l={name:"guide/installation.md"};function o(n,a,r,p,h,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Detailed installation and troubleshooting guide.</p><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><ul><li><strong>macOS</strong> 10.15 (Catalina) or later</li><li><strong>Internet connection</strong> for AI API calls</li><li><strong>API key</strong> from OpenAI or Google Gemini</li></ul><h2 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h2><h3 id="_1-download" tabindex="-1">1. Download <a class="header-anchor" href="#_1-download" aria-label="Permalink to &quot;1. Download&quot;">​</a></h3><ul><li><a href="/downloads.html">Download Grammar Assistant</a> (macOS only)</li><li>Choose the latest version for your Mac (Apple Silicon or Intel)</li></ul><h3 id="_2-install" tabindex="-1">2. Install <a class="header-anchor" href="#_2-install" aria-label="Permalink to &quot;2. Install&quot;">​</a></h3><ul><li>Open the <code>.dmg</code> file</li><li>Drag <strong>Grammar Assistant</strong> to <strong>Applications</strong> folder</li><li>Launch from Applications</li></ul><h3 id="_3-security-prompt-first-launch" tabindex="-1">3. Security Prompt (First Launch) <a class="header-anchor" href="#_3-security-prompt-first-launch" aria-label="Permalink to &quot;3. Security Prompt (First Launch)&quot;">​</a></h3><p><strong>If you see: <em>&quot;Grammar Assistant is damaged and can&#39;t be opened&quot;</em></strong></p><p>This happens because the app is not code-signed. Fix it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/Grammar Assistant.app&quot;</span></span></code></pre></div><p><strong>Alternative method:</strong></p><ol><li>Right-click (or Control-click) the app → <strong>Open</strong></li><li>If still blocked, open <strong>Terminal</strong> and run the command above</li></ol><p><strong>If you see: <em>&quot;Grammar Assistant cannot be opened because the developer cannot be verified&quot;</em></strong></p><ol><li>Right-click the app → <strong>Open</strong></li><li>Click <strong>Open</strong> in the confirmation dialog</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>These are one-time steps. macOS will remember your choice.</p></div><h3 id="_4-grant-accessibility-permission" tabindex="-1">4. Grant Accessibility Permission <a class="header-anchor" href="#_4-grant-accessibility-permission" aria-label="Permalink to &quot;4. Grant Accessibility Permission&quot;">​</a></h3><p>Required for Cmd+Shift+G to work:</p><ol><li><strong>System Settings</strong> → <strong>Privacy &amp; Security</strong> → <strong>Accessibility</strong></li><li>Click 🔒 to unlock (enter password)</li><li>Click <strong>+</strong> button</li><li>Find and add <strong>Grammar Assistant</strong></li><li>Restart the app</li></ol><details class="details custom-block"><summary>Why is this needed?</summary><p>Accessibility permission allows:</p><ul><li>Monitoring Cmd+Shift+G shortcut globally</li><li>Auto-copying selected text</li><li>Working across all apps</li></ul><p>The app only activates when YOU press the shortcut.</p></details><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="app-is-damaged-error" tabindex="-1">&quot;App is damaged&quot; Error <a class="header-anchor" href="#app-is-damaged-error" aria-label="Permalink to &quot;&quot;App is damaged&quot; Error&quot;">​</a></h3><p>If you see <em>&quot;Grammar Assistant is damaged and can&#39;t be opened&quot;</em>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/Grammar Assistant.app&quot;</span></span></code></pre></div><p>This removes the quarantine flag that macOS adds to downloaded apps.</p><h3 id="shortcut-not-working" tabindex="-1">Shortcut Not Working <a class="header-anchor" href="#shortcut-not-working" aria-label="Permalink to &quot;Shortcut Not Working&quot;">​</a></h3><p><strong>Check:</strong></p><ol><li>✅ Accessibility permission granted?</li><li>✅ App is running?</li><li>✅ Tried restarting the app?</li></ol><p><strong>Still not working?</strong></p><ul><li>Some apps may block shortcuts (rare)</li><li>Check macOS keyboard shortcuts for conflicts</li><li>Try in a different app (e.g., TextEdit)</li></ul><h3 id="app-crashes-or-won-t-start" tabindex="-1">App Crashes or Won&#39;t Start <a class="header-anchor" href="#app-crashes-or-won-t-start" aria-label="Permalink to &quot;App Crashes or Won&#39;t Start&quot;">​</a></h3><ol><li>Check macOS version (10.15+)</li><li>Try deleting app and reinstalling</li><li>Check Console.app for error logs</li></ol><h3 id="api-key-issues" tabindex="-1">API Key Issues <a class="header-anchor" href="#api-key-issues" aria-label="Permalink to &quot;API Key Issues&quot;">​</a></h3><ul><li>Make sure you copied the full key (no spaces)</li><li>Verify key is active on provider&#39;s dashboard</li><li>Check internet connection</li></ul><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><ol><li>Quit Grammar Assistant</li><li>Move app to Trash from Applications</li><li>(Optional) Remove settings:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/com.kitelus.grammar-assistant/</span></span></code></pre></div></li></ol><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><ul><li>📖 <a href="/guide/getting-started.html">Getting Started Guide</a></li><li>🔍 <a href="https://github.com/thanhbinhbent/grammar-assistant/issues" target="_blank" rel="noreferrer">Search Issues</a></li><li>✍️ <a href="https://github.com/thanhbinhbent/grammar-assistant/issues/new" target="_blank" rel="noreferrer">Create New Issue</a></li></ul>',40)])])}const g=t(l,[["render",o]]);export{u as __pageData,g as default};
